			function onBodyLoad(/* cpr.events.CEvent */ e){
			   
			    app.lookup("dsTrprInfo").addRow(); // 대상자정보 신규row 생성    
			    
			    var voInitValue = app.getHostProperty("initValue");
			    
			    if(! ValueUtil.isNull(voInitValue)){
			        var voDataSet = app.lookup("dsTrprInfo");
			        var voDataMap = app.lookup("dmSearch");
			        
			        // 호출페이지 대상자정보
			        voDataSet.setValue(0, "TRPR_INFO_NO"    , voInitValue["TRPR_INFO_NO"]);
			        voDataSet.setValue(0, "TRPR_NM"         , voInitValue["TRPR_NM"]);
			        voDataSet.setValue(0, "RRNO"            , voInitValue["RRNO_ENCPT"]);
			        voDataSet.setValue(0, "TRPR_BRTH_YMD"   , voInitValue["TRPR_BRTH_YMD"]);
			        voDataSet.setValue(0, "SXDC_SE_CD"      , voInitValue["SXDC_SE_CD"]);
			        voDataSet.setValue(0, "TRPR_TELNO"      , voInitValue["TRPR_TELNO"]);
			        voDataSet.setValue(0, "MBL_TELNO"       , voInitValue["MBL_TELNO"]);
			        voDataSet.setValue(0, "EML_ADDR"        , voInitValue["EML_ADDR"]);
			        voDataSet.setValue(0, "PST_ADDR"        , voInitValue["PST_ADDR"]);
			        voDataSet.setValue(0, "DADDR"           , voInitValue["DADDR"]);
			        
			        // 조회정보
			        voDataMap.setValue("CASE_MNG_NO"      , voInitValue["CASE_MNG_NO"]);           // 사례관리번호
			        voDataMap.setValue("CASE_MNG_ODRNO"   , voInitValue["CASE_MNG_ODRNO"]);        // 사례관리차수
			        
			        var sCaseMngNo    = voDataMap.getValue("CASE_MNG_NO");
			        var sCaseMngOdrno = voDataMap.getValue("CASE_MNG_ODRNO");
			        
			        if (sCaseMngNo == "" &&  sCaseMngOdrno == "" || sCaseMngNo == null && sCaseMngOdrno == null){
			            
			            var psTitle = "사례회의";
			            var psMsgId = "조회할 사례관리번호, 사례관리차수가 없습니다.";
			            util.Msg.alert(app, psMsgId, null, function(){
			                util.Control.setReadOnly(app, true, "grpData");
			            }, psTitle);
			            util.Control.redraw(app, "grpData");
			        }else{
			            
			            // 사례회의 조회
			            doList();
			        }
			    }    
			}

